package com.arqly.backend.notification;
import com.arqly.backend.entity.*;import com.arqly.backend.repository.*;import org.springframework.stereotype.Component;
@Component public class InAppNotificationChannel implements NotificationChannel {private final NotificationRepository notifications;private final TenantUserRepository users;public InAppNotificationChannel(NotificationRepository notifications,TenantUserRepository users){this.notifications=notifications;this.users=users;}public void dispatch(NotificationRequest r){if(notifications.existsByTenantIdAndRecipientUserIdAndDeduplicationKey(r.tenantId(),r.recipientUserId(),r.deduplicationKey()))return;var user=users.findByIdAndTenantId(r.recipientUserId(),r.tenantId()).orElse(null);if(user==null)return;var n=new Notification();n.setTenant(user.getTenant());n.setRecipientUser(user);n.setType(r.type());n.setCategory(r.category());n.setPriority(r.priority());n.setTitle(r.title());n.setMessage(r.message());n.setSourceType(r.sourceType());n.setSourceId(r.sourceId());n.setActionUrl(r.actionUrl());n.setDeduplicationKey(r.deduplicationKey());n.setMandatory(r.mandatory());n.setMessageKey(r.messageKey());n.setMetadata(r.metadata());notifications.save(n);}}
